begin;
create temporary table digest_assertions(label text,passed boolean,detail text);
alter table digest_assertions enable row level security;
create policy temporary_assertions on digest_assertions for all to anon,authenticated using(true) with check(true);
grant select,insert on digest_assertions to authenticated,anon;
do $$begin execute format('grant usage on schema %I to authenticated,anon',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end$$;
create function pg_temp.ok(value boolean,label text) returns boolean language plpgsql as $$begin insert into pg_temp.digest_assertions values(label,coalesce(value,false),null);return value;end$$;
create function pg_temp.denied(command text,expected text,label text) returns boolean language plpgsql as $$declare code text:='00000';detail text;begin begin execute command;exception when others then get stacked diagnostics code=returned_sqlstate,detail=message_text;end;insert into pg_temp.digest_assertions values(label,code=expected,case when code<>expected then code||':'||coalesce(detail,'No error')end);return code=expected;end$$;
insert into auth.users(id,email) values('a9300000-0000-0000-0000-000000000001','digest-c1@example.test'),('a9300000-0000-0000-0000-000000000002','digest-c2@example.test'),('a9300000-0000-0000-0000-000000000003','digest-staff@example.test');
insert into vb_private.staff_members(user_id) values('a9300000-0000-0000-0000-000000000003');
insert into public.vb_clients(id,name,client_type,contact_name,portal_enabled) values('b9300000-0000-0000-0000-000000000001','Digest fixture one','business','Fictional',true),('b9300000-0000-0000-0000-000000000002','Digest fixture two','business','Fictional',true);
insert into public.vb_marks(id,client_id,name,mark_type,status) values('c9300000-0000-0000-0000-000000000001','b9300000-0000-0000-0000-000000000001','EVIDENCE ONE','word','not_filed'),('c9300000-0000-0000-0000-000000000002','b9300000-0000-0000-0000-000000000002','EVIDENCE TWO','word','not_filed');
insert into vb_private.client_memberships(client_id,user_id) values('b9300000-0000-0000-0000-000000000001','a9300000-0000-0000-0000-000000000001'),('b9300000-0000-0000-0000-000000000002','a9300000-0000-0000-0000-000000000002');

insert into vb_private.client_memberships(client_id,user_id) values('b9300000-0000-0000-0000-000000000001','a9300000-0000-0000-0000-000000000002');
insert into public.vb_evidence(id,client_id,mark_id,uploaded_by,kind,captured_on,filename,mime_type,byte_size,content_sha256,object_path,uploaded_at) values('e9300000-0000-0000-0000-000000000001','b9300000-0000-0000-0000-000000000001','c9300000-0000-0000-0000-000000000001','a9300000-0000-0000-0000-000000000001','photo',current_date,'fixture.png','image/png',68,repeat('a',64),'digest-fixture.png',now());


select pg_temp.ok(vb_private.digest_next_due('2026-01-31 12:00Z','monthly')='2026-02-28 12:00Z'::timestamptz,'Monthly uses calendar month, including shorter months');
select pg_temp.ok(vb_private.digest_next_due('2026-10-10 12:00Z','weekly')='2026-10-17 12:00Z'::timestamptz,'Weekly uses seven days');
select pg_temp.ok(vb_private.digest_next_due('2026-10-10 12:00Z','daily')='2026-10-11 12:00Z'::timestamptz,'Daily uses one UTC day');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9300000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select public.vb_save_digest_preferences('b9300000-0000-0000-0000-000000000001',0,'{"categories":["use_history"],"frequency":"weekly","delivery":"account"}');
select pg_temp.ok((select next_due_at=period_start+interval '7 days' from public.vb_digest_preferences where client_id='b9300000-0000-0000-0000-000000000001'),'New settings schedule first delivery after selected interval');
reset role;
create temporary table before_save as select period_start,next_due_at from public.vb_digest_preferences where client_id='b9300000-0000-0000-0000-000000000001';
set local role authenticated;
select public.vb_save_digest_preferences('b9300000-0000-0000-0000-000000000001',1,'{"categories":["bcm","use_history"],"frequency":"weekly","delivery":"account"}');
reset role;
select pg_temp.ok((select p.next_due_at=b.next_due_at from public.vb_digest_preferences p cross join before_save b where client_id='b9300000-0000-0000-0000-000000000001'),'Category changes do not postpone schedule');
set local role authenticated;
select public.vb_save_digest_preferences('b9300000-0000-0000-0000-000000000001',2,'{"categories":["use_history"],"frequency":"monthly","delivery":"account"}');
reset role;
select pg_temp.ok((select next_due_at=vb_private.digest_next_due(now(),'monthly') from public.vb_digest_preferences where client_id='b9300000-0000-0000-0000-000000000001'),'Frequency change sets new due date');
select pg_temp.ok(vb_private.deliver_due_digests()=0,'Not-yet-due preference does not deliver');
update public.vb_digest_preferences set period_start=now()-interval '3 months',next_due_at=now()-interval '2 months' where client_id='b9300000-0000-0000-0000-000000000001';
select pg_temp.ok(vb_private.deliver_due_digests()=1,'Overdue recipient receives one digest');
select pg_temp.ok(vb_private.deliver_due_digests()=0,'Retry does not duplicate delivery');
select pg_temp.ok((select count(*)=1 and bool_and(kind='digest' and read_at is null and jsonb_array_length(source_items)=1) from public.vb_inbox where client_id='b9300000-0000-0000-0000-000000000001'),'One unread digest contains selected authoritative upload');
select pg_temp.ok((select period_start=now() and next_due_at=vb_private.digest_next_due(now(),'monthly') from public.vb_digest_preferences where client_id='b9300000-0000-0000-0000-000000000001'),'Successful delivery advances period and next due');
select pg_temp.denied($$insert into public.vb_inbox(recipient_id,client_id,kind,categories,frequency,period_start,scheduled_for,source_items) select recipient_id,client_id,kind,categories,frequency,period_start,scheduled_for,source_items from public.vb_inbox where client_id='b9300000-0000-0000-0000-000000000001'$$,'23505','Unique schedule prevents duplicate period');
update public.vb_digest_preferences set next_due_at=now()-interval '1 minute' where client_id='b9300000-0000-0000-0000-000000000001';
update public.vb_clients set portal_enabled=false where id='b9300000-0000-0000-0000-000000000001';
select pg_temp.ok(vb_private.deliver_due_digests()=0,'Disabled portal stops delivery');
update public.vb_clients set portal_enabled=true,archived_at=now() where id='b9300000-0000-0000-0000-000000000001';
select pg_temp.ok(vb_private.deliver_due_digests()=0,'Archived client stops delivery');
update public.vb_clients set archived_at=null where id='b9300000-0000-0000-0000-000000000001';
update public.vb_clients set portal_enabled=true where id='b9300000-0000-0000-0000-000000000001';
update vb_private.client_memberships set active=false where user_id='a9300000-0000-0000-0000-000000000001';
select pg_temp.ok(vb_private.deliver_due_digests()=0,'Revoked membership stops delivery');
update vb_private.client_memberships set active=true where user_id='a9300000-0000-0000-0000-000000000001';
insert into vb_private.staff_members(user_id) values('a9300000-0000-0000-0000-000000000001');
select pg_temp.ok(vb_private.deliver_due_digests()=0,'Staff account with membership cannot receive client digest');
delete from vb_private.staff_members where user_id='a9300000-0000-0000-0000-000000000001';
create temporary table schedule_message_id as select id from public.vb_inbox where client_id='b9300000-0000-0000-0000-000000000001';
grant select on schedule_message_id to authenticated;alter table schedule_message_id enable row level security;create policy fixture_message on schedule_message_id for select to authenticated using(true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9300000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}',true);
select pg_temp.ok((select count(*)=0 from public.vb_inbox where client_id='b9300000-0000-0000-0000-000000000001'),'Same-client other recipient cannot read scheduled message');
select pg_temp.denied($$select public.vb_open_inbox('b9300000-0000-0000-0000-000000000001',(select id from schedule_message_id))$$,'42501','Other recipient cannot open scheduled message');
select pg_temp.denied('select vb_private.deliver_due_digests()','42501','Client cannot invoke worker');
select set_config('request.jwt.claims','{"sub":"a9300000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select pg_temp.ok(public.vb_open_inbox('b9300000-0000-0000-0000-000000000001',(select id from schedule_message_id))->>'kind'='digest','Recipient opens scheduled message with correct kind');
select pg_temp.ok((select read_at is not null from public.vb_inbox where client_id='b9300000-0000-0000-0000-000000000001'),'Scheduled message read status persists');
reset role;
update public.vb_evidence set removed_at=now(),removed_by='a9300000-0000-0000-0000-000000000001' where id='e9300000-0000-0000-0000-000000000001';
set local role authenticated;
select pg_temp.ok(jsonb_array_length(public.vb_open_inbox('b9300000-0000-0000-0000-000000000001',(select id from schedule_message_id))->'items')=0,'Removed upload excluded when scheduled message reopened');
reset role;
set local role anon;
select pg_temp.denied('select vb_private.deliver_due_digests()','42501','Signed-out caller cannot invoke worker');
reset role;
select pg_temp.ok(not has_function_privilege('service_role','vb_private.deliver_due_digests()','EXECUTE'),'API service role cannot invoke scheduler');
select jsonb_build_object('executed',count(*),'all_passed',bool_and(passed),'assertions',jsonb_agg(to_jsonb(a))) as scheduling_tests from pg_temp.digest_assertions a;
rollback;
